# ---- merge, validate, write back ----
existing_ids={x["id"] for x in d["domains"]}
for nd in new_domains:
    assert nd["id"] not in existing_ids, "duplicate domain "+nd["id"]
d["domains"].extend(new_domains)
d["lessons"].extend(new_lessons)
dmap={x["id"]:x for x in d["domains"]}
for s in scenarios:
    assert s["id"] not in {z["id"] for x in d["domains"] for z in x.get("scenarios",[])}, "dup scenario "+s["id"]
    dmap[s["domain_id"]]["scenarios"].append(s)
existing_lab_ids={l["id"] for l in d["labs"]}
for l in labs:
    assert l["id"] not in existing_lab_ids, "dup lab "+l["id"]
d["labs"].extend(labs)

# validate shapes
for l in new_lessons:
    assert set(["domain_id","title","concepts","example","pitfalls","try_it"])<=set(l.keys()), l["title"]
    assert len(l["concepts"])>=4 and len(l["pitfalls"])>=3, l["title"]
    assert "code" in l["example"] and "walkthrough" in l["example"]
for x in d["domains"]:
    for s in x.get("scenarios",[]):
        assert len(s["choices"])==4 and 0<=s["answer"]<4, s["id"]
        assert all(len(ev)==2 for ev in s["evidence"]), s["id"]
        assert isinstance(s["mins"],int)
for l in labs:
    assert set(["id","title","objective","steps","checks","success_message"])<=set(l.keys()), l["id"]

with open(PATH+".new","w") as f:
    json.dump(d,f,ensure_ascii=False,indent=1)
import os; os.replace(PATH+".new",PATH)
d2=json.load(open(PATH))
print("SQL FINAL:",len(d2["domains"]),len(d2["lessons"]),sum(len(x.get("scenarios",[])) for x in d2["domains"]),len(d2.get("labs",[])))
